INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Hashfunktion wie SHA-256 auch eine Verschlüsselung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Einwegfunktion, kein Rückschluss"}, {"text": "Ja", "correct": false, "because": "Verschlüsselung ist umkehrbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit SHA-256 in meinem Projekt?', 3, '[{"text": "Integritätssicherung", "correct": true, "because": "Prüft Datenveränderungen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht dafür gedacht"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen SHA-256 sicher?', 5, '[{"text": "Kollisionsresistenz", "correct": true, "because": "Schwer zwei gleiche Hashes zu finden"}, {"text": "Einwegfunktion", "correct": true, "because": "Nicht umkehrbar"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Sicherheit vor Geschwindigkeit"}, {"text": "Variable Länge", "correct": false, "because": "Feste 256-Bit-Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SHA-256 erzeugt immer 256 Bit. b) Es ist für Passwortverschlüsselung ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwörter brauchen Salt und Iterationen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht ideal"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von SHA-256 für Integrität?', 4, '[{"text": "Kollisionswahrscheinlichkeit", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Eingabelänge", "correct": false, "because": "Beeinflusst Hashzeit"}, {"text": "Farbausgabe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SHA-256 auch Authentizität sicherstellt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Integrität, HMAC für Authentizität"}, {"text": "Ja", "correct": false, "because": "Fehlt Signaturfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Algorithmus wähle ich für eine Prüfsumme bei großen Dateien?', 3, '[{"text": "SHA-256", "correct": true, "because": "Sicher und weit verbreitet"}, {"text": "MD5", "correct": false, "because": "Weniger sicher"}, {"text": "CRC32", "correct": false, "because": "Schneller, aber unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Hashfunktionen wie SHA-256?', 5, '[{"text": "Dateiintegrität", "correct": true, "because": "Prüft Veränderungen"}, {"text": "Blockchain", "correct": true, "because": "Sichert Transaktionen"}, {"text": "Datenkompression", "correct": false, "because": "Falsche Funktion"}, {"text": "Bandbreitensteigerung", "correct": false, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SHA-256 ist sicherer als SHA-1. b) Es ist für große Daten ungeeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geeignet für alle Datengrößen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SHA-256 in einer Sicherheitslösung?', 4, '[{"text": "Eingabedaten", "correct": false, "because": "Grundlage des Hashs"}, {"text": "Hashwert", "correct": false, "because": "Ergebnis der Funktion"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Technische Umsetzung reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich mit SHA-256 Daten entschlüsseln?', 2, '[{"text": "Nein", "correct": true, "because": "Einwegfunktion"}, {"text": "Ja", "correct": false, "because": "Nur Hashing, keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen SHA-256 für Integrität geeignet?', 4, '[{"text": "Feste Ausgabelänge", "correct": true, "because": "256 Bit konsistent"}, {"text": "Deterministisch", "correct": true, "because": "Gleiche Eingabe, gleicher Hash"}, {"text": "Hohe Kompression", "correct": false, "because": "Kein Kompressionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SHA-256 für Passwörter ohne Salt sicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Salt schützt vor Rainbow-Tables"}, {"text": "Ja", "correct": false, "because": "Ohne Salt unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Faktor priorisiere ich bei SHA-256 für Dateiintegrität?', 3, '[{"text": "Kollisionsresistenz", "correct": true, "because": "Verhindert falsche Übereinstimmungen"}, {"text": "Schnelle Berechnung", "correct": false, "because": "Sicherheit vor Geschwindigkeit"}, {"text": "Einfache Implementierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SHA-256 ist kryptografisch sicher. b) Es komprimiert Daten effizient.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Kompression"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren von SHA-256?', 5, '[{"text": "Software-Downloads", "correct": true, "because": "Prüft Integrität"}, {"text": "Digitale Signaturen", "correct": true, "because": "Sichert Echtheit"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Netzwerkoptimierung", "correct": false, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei SHA-256 für Prüfsummen unwichtig?', 3, '[{"text": "Hashlänge", "correct": false, "because": "Definiert Sicherheit"}, {"text": "Eingabedaten", "correct": false, "because": "Grundlage des Hashs"}, {"text": "Anzeigefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SHA-256 schneller als MD5?', 3, '[{"text": "Nein", "correct": true, "because": "Sicherheit kostet Rechenzeit"}, {"text": "Ja", "correct": false, "because": "MD5 ist weniger komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SHA-256 für kleine Daten übertrieben ist?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit unabhängig von Größe"}, {"text": "Ja", "correct": false, "because": "Auch kleine Daten schützen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Algorithmus wähle ich für eine sichere Prüfsumme?', 4, '[{"text": "SHA-256", "correct": true, "because": "Hohe Sicherheit, weit akzeptiert"}, {"text": "CRC32", "correct": false, "because": "Schnell, aber unsicher"}, {"text": "Adler-32", "correct": false, "because": "Weniger robust"}]');
